-- ===========================================================================
-- Seed 18 : quizzes for the Ruby course
--
-- One per level. The scratchpad on each quiz page opens on a Ruby starter,
-- because starter_for_course() reads the course slug - so a learner unsure of
-- an answer can run the snippet rather than argue with themselves about it.
--
-- Generated by scratchpad/gen/build_ruby_quizzes.py, which also checks that every
-- single_choice has exactly one correct option and every multiple_choice has
-- at least two. A quiz that cannot be passed is not obvious from the SQL.
-- ===========================================================================

INSERT INTO assessment_quizzes
  (id, course_id, lesson_id, title, description, pass_percent, time_limit_seconds,
   max_attempts, shuffle_questions, shuffle_options, show_answers, status)
VALUES
  ('f0000001-0000-4000-8000-00000000001c',
   'c0000001-0000-4000-8000-00000000000a', 'e0000001-0000-4000-8000-00000000007d',
   'Level 1 Check: Objects, Flow and Collections',
   'Truthiness, the three kinds of equality, and the Enumerable methods. Every one of these can be settled in the scratchpad below the questions.',
   60, 600, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000001d',
   'c0000001-0000-4000-8000-00000000000a', 'e0000001-0000-4000-8000-00000000007e',
   'Level 2 Check: Symbols, Mixins and Failure',
   'Strings against symbols, the method lookup chain, and rescuing the right thing.',
   60, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000001e',
   'c0000001-0000-4000-8000-00000000000a', 'e0000001-0000-4000-8000-00000000007f',
   'Level 3 Check: Blocks, Laziness and Reflection',
   'Procs against lambdas, building an Enumerable, and what metaprogramming costs.',
   70, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000001f',
   'c0000001-0000-4000-8000-00000000000a', 'e0000001-0000-4000-8000-000000000080',
   'Expert Exam: Ruby',
   'Pattern matching, where the time goes, and how an application is arranged.',
   70, 1500, 3, 1, 1, 1, 'published')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), description = VALUES(description),
  pass_percent = VALUES(pass_percent), status = VALUES(status);

INSERT INTO assessment_questions
  (id, quiz_id, kind, prompt, explanation, points, `position`, correct_text)
VALUES
  -- Level 1 Check: Objects, Flow and Collections
  ('a1000001-0000-4000-8000-000000000281', 'f0000001-0000-4000-8000-00000000001c', 'single_choice',
   'Which values are falsy in Ruby?',
   'Only false and nil. Zero, an empty string, an empty array and an empty hash are all truthy - which is why `if basket` does not tell you whether the basket has anything in it. Ask `basket.empty?` instead.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000282', 'f0000001-0000-4000-8000-00000000001c', 'single_choice',
   'What does `1.eql?(1.0)` return, and why?',
   'false. `==` compares value and treats 1 and 1.0 as equal; `eql?` also requires the same type, and Integer is not Float. `equal?` is stricter still - it asks whether the two are the same object.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000283', 'f0000001-0000-4000-8000-00000000001c', 'multiple_choice',
   'Which statements about `case` in Ruby are true? Select all that apply.',
   'case uses ===, which each class defines for itself: a Range asks whether the value falls inside it, a Class asks whether the value is an instance, a Regexp asks whether it matches. case is also an expression, so it returns a value. It does not need break, and it does not fall through.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-000000000284', 'f0000001-0000-4000-8000-00000000001c', 'single_choice',
   'You have an array of hashes and want the names of everyone scoring 80 or more. Which reads best?',
   'select then map. select narrows the collection, map turns each survivor into what you want, and the chain reads in the order it happens. Writing the loop by hand works, but a reader has to reconstruct the intent from the body.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-000000000285', 'f0000001-0000-4000-8000-00000000001c', 'true_false',
   '`hash[:missing]` raises a KeyError when the key is not present.',
   'False. `[]` returns nil for a missing key, which is why a typo in a key name shows up much later as a NoMethodError on nil. `fetch` is the one that raises, and it also takes a default: `hash.fetch(:missing, 0)`.',
   2, 5, NULL),

  -- Level 2 Check: Symbols, Mixins and Failure
  ('a1000001-0000-4000-8000-000000000286', 'f0000001-0000-4000-8000-00000000001d', 'single_choice',
   'When should you use a symbol rather than a string?',
   'For names: hash keys, method names, fixed identifiers. Two identical symbols are the same object, so comparing them is fast and writing one allocates nothing after the first time. Strings are for text that came from a user or is shown to one.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000287', 'f0000001-0000-4000-8000-00000000001d', 'multiple_choice',
   'Which of these avoid allocating a new String object? Select all that apply.',
   '`<<` appends to the receiver rather than building a new one, and `join` allocates a single buffer sized once for the whole result. `-"text"` returns a shared frozen instance, so evaluating it repeatedly allocates once. `a + b` allocates a new string on every evaluation.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-000000000288', 'f0000001-0000-4000-8000-00000000001d', 'single_choice',
   'A class includes a module, and both define `render`. Which one runs?',
   'The class''s. `include` inserts the module into the lookup chain just above the class, so the class''s own method is found first and the module''s is the fallback. `Klass.ancestors` prints the chain, and is the fastest way to settle any question like this.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-000000000289', 'f0000001-0000-4000-8000-00000000001d', 'single_choice',
   'Why should you write `rescue => e` rather than `rescue Exception => e`?',
   'A bare rescue catches StandardError, which is everything a program can reasonably handle. Exception also covers SignalException, SystemExit and NoMemoryError - so `rescue Exception` swallows the user pressing Ctrl-C and the program''s own attempt to exit.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-00000000028a', 'f0000001-0000-4000-8000-00000000001d', 'single_choice',
   'You expect some entries in a list of strings not to be numbers. What is the best way to sum the ones that are?',
   '`Integer(text, exception: false)` returns nil instead of raising, so an expected outcome stays a value. Wrapping each entry in begin/rescue costs an exception per bad entry and buries the intent; a bare rescue would also hide a real typo in your own code.',
   3, 5, NULL),

  -- Level 3 Check: Blocks, Laziness and Reflection
  ('a1000001-0000-4000-8000-00000000028b', 'f0000001-0000-4000-8000-00000000001e', 'multiple_choice',
   'How does a lambda differ from a proc? Select all that apply.',
   'A lambda checks its arity and raises ArgumentError on the wrong number of arguments; a proc fills missing ones with nil. `return` in a lambda returns from the lambda, while `return` in a proc returns from the method that created it. Both are instances of Proc, and `lambda?` is what tells them apart.',
   3, 1, NULL),

  ('a1000001-0000-4000-8000-00000000028c', 'f0000001-0000-4000-8000-00000000001e', 'single_choice',
   'What do you have to write to make your own class work with `map`, `select`, `sum` and `min_by`?',
   'Define `each` and `include Enumerable`. Every other method in the module is built on `each`, so one method buys about sixty. Returning `to_enum(:each)` when no block is given is the finishing touch that lets callers chain `.with_index`.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-00000000028d', 'f0000001-0000-4000-8000-00000000001e', 'single_choice',
   'What does `(1..Float::INFINITY).lazy.map { |n| n * n }.first(3)` do?',
   'It returns [1, 4, 9] having done three multiplications. A lazy chain passes one element through every step before starting the next, so it never tries to build the intermediate array - which is what makes an infinite source safe. Without `lazy` the same expression never returns.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-00000000028e', 'f0000001-0000-4000-8000-00000000001e', 'single_choice',
   'You define `method_missing` on a class. What else must you define, and why?',
   '`respond_to_missing?`. Without it the object answers false to `respond_to?` for methods it actually handles, and `method(:name)` raises - so anything that introspects before calling, including much of the standard library, misbehaves. Falling through to `super` for names you do not handle is the other half: it keeps a real typo raising NoMethodError.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-00000000028f', 'f0000001-0000-4000-8000-00000000001e', 'multiple_choice',
   'Which are good reasons to prefer `define_method` over `method_missing`? Select all that apply.',
   'define_method creates real methods, so they appear in `instance_methods`, can be found by grep and by an editor, and are dispatched at normal speed. method_missing only runs after the whole lookup chain has failed, which is slower and invisible to anyone reading the code. Neither has anything to do with thread safety.',
   3, 5, NULL),

  -- Expert Exam: Ruby
  ('a1000001-0000-4000-8000-000000000290', 'f0000001-0000-4000-8000-00000000001f', 'multiple_choice',
   'Which statements about `case/in` pattern matching are true? Select all that apply.',
   'A hash pattern matches on the keys it names and ignores any others, so an extra field never breaks the match. An array pattern must account for every element, though `*` can absorb a run. A value with no matching branch and no else raises NoMatchingPatternError - which is the feature, because it turns a forgotten state into a loud failure. `^` pins an existing variable so it is compared rather than rebound.',
   3, 1, NULL),

  ('a1000001-0000-4000-8000-000000000291', 'f0000001-0000-4000-8000-00000000001f', 'single_choice',
   'Which methods must a class define to take part in both array and hash patterns?',
   '`deconstruct` for array patterns and `deconstruct_keys` for hash patterns. Data and Struct define both already, which is why they work in a `case/in` with no extra code. `deconstruct_keys` receives the keys the pattern asked for, so an expensive field can be computed only when it is needed.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-000000000292', 'f0000001-0000-4000-8000-00000000001f', 'single_choice',
   'A loop calls `authors.find { |a| a[:id] == book[:author_id] }` once per book. What is the fix?',
   'Build the index once, then look up by key. `authors.to_h { |a| [a[:id], a] }` turns two thousand scans into two thousand hash hits, and the same shape - fetch once, key it, then look up - is the fix for the N+1 query in a real application.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-000000000293', 'f0000001-0000-4000-8000-00000000001f', 'single_choice',
   'Why is `@empty ||= @rows.empty?` a broken memoisation?',
   '`||=` re-runs whenever the stored value is nil or false, so a legitimately false answer is recomputed on every call. `return @empty if defined?(@empty)` asks whether the variable was set, which is the question you actually meant.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-000000000294', 'f0000001-0000-4000-8000-00000000001f', 'multiple_choice',
   'You are arranging an application so a change stays small. Which of these help? Select all that apply.',
   'Dependencies point inwards: the entity knows nothing about the web or the database, and the service is handed its collaborators rather than reaching for them - which is what makes a fake repository one keyword argument. At the boundary an expected failure is a result the caller must handle, not an exception. Naming after the pattern rather than the domain tells a reader nothing, and a unit test that needs a database means the logic ended up in the wrong layer.',
   4, 5, NULL)
ON DUPLICATE KEY UPDATE
  prompt = VALUES(prompt), explanation = VALUES(explanation),
  points = VALUES(points), correct_text = VALUES(correct_text);

DELETE FROM assessment_question_options
 WHERE question_id IN (
   SELECT id FROM assessment_questions
    WHERE quiz_id IN ('f0000001-0000-4000-8000-00000000001c',
                      'f0000001-0000-4000-8000-00000000001d',
                      'f0000001-0000-4000-8000-00000000001e',
                      'f0000001-0000-4000-8000-00000000001f'));

INSERT INTO assessment_question_options (question_id, body, is_correct, `position`)
SELECT v.question_id, v.body, v.is_correct, v.pos
  FROM (
    SELECT 'a1000001-0000-4000-8000-000000000281' AS question_id, 'false and nil, and nothing else' AS body, 1 AS is_correct, 1 AS pos
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000281', 'false, nil, 0 and ""', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000281', 'false, nil, 0, "" and []', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000281', 'Only false; nil is truthy', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000282', 'false, because eql? also requires the same type', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000282', 'true, because eql? is an alias for ==', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000282', 'false, because eql? compares object identity', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000282', 'It raises a TypeError comparing Integer with Float', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000283', 'It compares with ===, not ==', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000283', 'A Range, a Class and a Regexp all work as conditions', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000283', 'It is an expression and returns a value', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000283', 'Each branch needs a break or it falls through to the next', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000284', 'learners.select { |l| l[:score] >= 80 }.map { |l| l[:name] }', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000284', 'learners.map { |l| l[:name] if l[:score] >= 80 }', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000284', 'learners.each { |l| names << l[:name] if l[:score] >= 80 }', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000284', 'learners.reduce([]) { |acc, l| l[:score] >= 80 ? acc << l[:name] : acc }', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000285', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000285', 'False', 1, 2

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000286', 'For names and identifiers, because the same symbol is one shared object', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000286', 'For any text that will not change, because symbols are frozen strings', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000286', 'For user input, because symbols cannot be mutated by an attacker', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000286', 'Whenever the text is short, because symbols use less memory per character', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000287', 'buffer << part', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000287', 'parts.join(",")', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000287', '-"a repeated literal"', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000287', 'result = result + part', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000288', 'The class''s, because include puts the module above the class in the chain', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000288', 'The module''s, because including it overwrites the class''s method', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000288', 'Whichever was defined last in the file', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000288', 'Neither - Ruby raises an error about the conflict', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000289', 'A bare rescue catches StandardError; Exception also catches interrupts and exits', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000289', 'They are identical, but the shorter form is conventional', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000289', 'rescue Exception is slower because the hierarchy is deeper', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000289', 'rescue Exception cannot bind the exception to a variable', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028a', 'numbers.sum { |t| Integer(t, exception: false) || 0 }', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028a', 'Wrap each Integer(t) in begin/rescue ArgumentError and return 0', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028a', 'numbers.sum { |t| t.to_i }, because to_i never raises', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028a', 'Rescue at the top of the method so one bad entry aborts the sum', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028b', 'A lambda raises on the wrong number of arguments; a proc does not', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028b', 'return in a lambda returns from the lambda; in a proc it returns from the enclosing method', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028b', 'They are different classes: Lambda and Proc', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028b', 'A proc cannot be passed to a method with &', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028c', 'An each method, plus include Enumerable', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028c', 'A to_a method, plus include Enumerable', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028c', 'map, select, sum and min_by, one at a time', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028c', 'A <=> method, plus include Comparable', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028d', 'Returns [1, 4, 9], having squared exactly three numbers', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028d', 'Hangs, because the range is infinite', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028d', 'Returns [1, 4, 9] after squaring every number up to a large internal limit', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028d', 'Raises a RangeError, because Float::INFINITY is not a valid range end', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028e', 'respond_to_missing?, or the object lies about what it can do', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028e', 'method_added, so Ruby knows the method now exists', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028e', 'define_method, because method_missing cannot return a value on its own', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028e', 'Nothing - respond_to? consults method_missing automatically', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028f', 'The methods are real, so instance_methods and grep both find them', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028f', 'Dispatch is at normal speed, with no failed lookup first', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028f', 'The block can close over local variables, which def cannot', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-00000000028f', 'method_missing is not thread safe', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000290', 'A hash pattern ignores keys it does not mention', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000290', 'An unmatched value with no else raises NoMatchingPatternError', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000290', '^name compares against an existing variable instead of binding a new one', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000290', 'An array pattern also ignores elements it does not mention', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000291', 'deconstruct and deconstruct_keys', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000291', 'to_a and to_h', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000291', '=== and ==', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000291', 'match? and deconstruct', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000292', 'Build a hash keyed by id once, then look up by key inside the loop', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000292', 'Sort the authors first, so find stops earlier on average', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000292', 'Replace find with detect, which short-circuits', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000292', 'Wrap the loop in lazy so the lookups are deferred', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000293', '||= recomputes whenever the cached value is false or nil', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000293', '||= is not thread safe, so two callers can compute it at once', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000293', 'Instance variables cannot hold booleans in Ruby', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000293', 'It works, but allocates a new object on every call', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000294', 'Keep the rules in plain objects that know nothing about the framework', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000294', 'Pass collaborators in as keyword arguments with sensible defaults', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000294', 'Return a result object at the edge for expected failures', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000294', 'Name classes after the pattern, so OrderServiceManagerImpl', 0, 4
  ) v;

CALL catalog_refresh_course_rollup('c0000001-0000-4000-8000-00000000000a');
CALL search_reindex_all();
